#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Fill training feedback HWPX template using JSON values.

- Reads /root/training_feedback.json
- Copies /root/training_feedback_template.hwpx -> /root/training_feedback_ready.hwpx
- Replaces {{...}} placeholders inside XML text nodes
- Removes stale layout-cache elements (lineSeg/lineseg*) from paragraphs whose text changed
- Rebuilds the HWPX (zip) preserving original entries and compression types
- Validates: output is a zip, no placeholders remain
"""

from __future__ import annotations

import json
import os
import re
import shutil
import sys
import zipfile

TEMPLATE_PATH = "/root/training_feedback_template.hwpx"
JSON_PATH = "/root/training_feedback.json"
OUTPUT_PATH = "/root/training_feedback_ready.hwpx"

PLACEHOLDER_RE = re.compile(r"{{\s*([^}]+?)\s*}}")

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"


def local_name(tag: str) -> str:
    if tag is None:
        return ""
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def is_layout_cache_element(tag: str) -> bool:
    ln = local_name(tag)
    if not ln:
        return False
    ln_low = ln.lower()
    # HWPX commonly uses linesegarray/lineSegArray, lineseg/LineSeg, etc.
    return ("lineseg" in ln_low) or ("linesegarray" in ln_low) or ("lineseg" in ln)


def copy_zipinfo(src: zipfile.ZipInfo) -> zipfile.ZipInfo:
    zi = zipfile.ZipInfo(filename=src.filename, date_time=src.date_time)
    zi.compress_type = src.compress_type
    zi.comment = src.comment
    zi.extra = src.extra
    zi.internal_attr = src.internal_attr
    zi.external_attr = src.external_attr
    zi.create_system = src.create_system
    zi.create_version = src.create_version
    zi.extract_version = src.extract_version
    zi.flag_bits = src.flag_bits
    zi.volume = src.volume
    zi.reserved = src.reserved
    zi.compresslevel = getattr(src, "compresslevel", None)
    return zi


def parse_score(value: str) -> float:
    m = re.search(r"(\d+(?:\.\d+)?)", str(value))
    if not m:
        raise ValueError(f"Cannot parse numeric score from: {value!r}")
    return float(m.group(1))


def digits_only(value: str) -> str:
    digits = re.findall(r"\d+", str(value))
    return "".join(digits)


def build_replacer(data: dict, replacements_log: list[dict], file_name: str):
    def repl(match: re.Match) -> str:
        key = match.group(1).strip()

        if key not in data:
            # Replace with empty string to ensure no {{...}} remain.
            replacements_log.append(
                {
                    "file": file_name,
                    "placeholder": key,
                    "from": match.group(0),
                    "to": "",
                    "note": "MISSING_KEY",
                }
            )
            return ""

        raw_val = data[key]
        if key == "참석자수":
            out = digits_only(raw_val)
        elif key == "만족도":
            score = parse_score(raw_val)
            out = f"{score:.1f}점 (5.0점 만점)"
        elif key == "종합의견":
            base = str(raw_val)
            suffix = "후속 심화반 검토 요망."
            if base and base[-1].isspace():
                out = base + suffix
            else:
                out = base + " " + suffix
        else:
            out = str(raw_val)

        replacements_log.append(
            {
                "file": file_name,
                "placeholder": key,
                "from": match.group(0),
                "to": out,
                "note": "",
            }
        )
        return out

    return repl


def process_xml_bytes(xml_bytes: bytes, json_data: dict, file_name: str, replacements_log: list[dict]):
    """Return (new_xml_bytes, changed:boolean, extracted_text:str)."""

    # Prefer lxml if available (better namespace/prefix preservation).
    try:
        from lxml import etree  # type: ignore

        parser = etree.XMLParser(remove_blank_text=False, recover=False)
        root = etree.fromstring(xml_bytes, parser=parser)

        changed_any = False

        # Iterate paragraphs (<hp:p> but keep namespace-agnostic).
        paragraphs = root.xpath(".//*[local-name()='p']")
        replacer = build_replacer(json_data, replacements_log, file_name)

        for p in paragraphs:
            p_changed = False

            # Replace placeholders only in text nodes.
            for t in p.xpath(".//*[local-name()='t']"):
                if t.text and "{{" in t.text:
                    before = t.text
                    after = PLACEHOLDER_RE.sub(replacer, before)
                    if after != before:
                        t.text = after
                        p_changed = True

            if p_changed:
                changed_any = True
                # Remove stale layout caches within this paragraph.
                for node in p.xpath(".//*[contains(translate(local-name(), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'), 'lineseg')]"):
                    parent = node.getparent()
                    if parent is not None:
                        parent.remove(node)

        new_bytes = etree.tostring(
            root,
            encoding="utf-8",
            xml_declaration=True,
            pretty_print=False,
        )

        extracted = []
        for t in root.xpath(".//*[local-name()='t']"):
            if t.text:
                extracted.append(t.text)
        return new_bytes, changed_any, "\n".join(extracted)

    except Exception:
        # Fallback to xml.etree.ElementTree
        import xml.etree.ElementTree as ET

        ET.register_namespace("hp", HP_NS)

        root = ET.fromstring(xml_bytes)
        changed_any = False
        replacer = build_replacer(json_data, replacements_log, file_name)

        def iter_paragraphs(elem):
            for e in elem.iter():
                if local_name(e.tag) == "p":
                    yield e

        def remove_cache_recursive(elem):
            for child in list(elem):
                if is_layout_cache_element(child.tag):
                    elem.remove(child)
                else:
                    remove_cache_recursive(child)

        for p in iter_paragraphs(root):
            p_changed = False
            for e in p.iter():
                if local_name(e.tag) == "t" and e.text and "{{" in e.text:
                    before = e.text
                    after = PLACEHOLDER_RE.sub(replacer, before)
                    if after != before:
                        e.text = after
                        p_changed = True

            if p_changed:
                changed_any = True
                remove_cache_recursive(p)

        new_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)

        extracted = []
        for e in root.iter():
            if local_name(e.tag) == "t" and e.text:
                extracted.append(e.text)
        return new_bytes, changed_any, "\n".join(extracted)


def main() -> int:
    # 1) Load JSON
    with open(JSON_PATH, "r", encoding="utf-8") as f:
        json_data = json.load(f)

    # 2) Copy template to output first
    shutil.copyfile(TEMPLATE_PATH, OUTPUT_PATH)

    # 3) Rebuild ZIP from the copied output
    tmp_out = OUTPUT_PATH + ".tmp"

    replacements_log: list[dict] = []
    modified_text_by_file: dict[str, str] = {}

    with zipfile.ZipFile(OUTPUT_PATH, "r") as zin, zipfile.ZipFile(tmp_out, "w") as zout:
        for info in zin.infolist():
            data = zin.read(info.filename)

            out_data = data
            modified = False

            if info.filename.lower().endswith(".xml") and b"{{" in data:
                out_data, modified, extracted_text = process_xml_bytes(
                    data,
                    json_data=json_data,
                    file_name=info.filename,
                    replacements_log=replacements_log,
                )
                if modified:
                    modified_text_by_file[info.filename] = extracted_text

            zi = copy_zipinfo(info)
            zout.writestr(zi, out_data)

    os.replace(tmp_out, OUTPUT_PATH)

    # 4) Validate output
    with zipfile.ZipFile(OUTPUT_PATH, "r") as z:
        bad = z.testzip()
        if bad is not None:
            raise RuntimeError(f"Corrupt zip entry detected: {bad}")

        remaining = []
        for name in z.namelist():
            b = z.read(name)
            if b"{{" in b or b"}}" in b:
                remaining.append(name)

    # 5) Print verification summaries
    print("=== Output written ===")
    print(OUTPUT_PATH)
    print()

    print("=== Replacement summary (by placeholder) ===")
    by_key: dict[str, int] = {}
    for r in replacements_log:
        by_key[r["placeholder"]] = by_key.get(r["placeholder"], 0) + 1
    for k in sorted(by_key.keys()):
        print(f"- {k}: {by_key[k]} occurrence(s)")

    missing = [r for r in replacements_log if r.get("note") == "MISSING_KEY"]
    if missing:
        print("\nWARNING: missing keys encountered:")
        for r in missing:
            print(f"- file={r['file']} placeholder={r['placeholder']}")

    print("\n=== Modified XML files (extracted text) ===")
    for fn, txt in modified_text_by_file.items():
        print(f"--- {fn} ---")
        print(txt)

    if remaining:
        print("\nERROR: Placeholders still present in:")
        for n in remaining:
            print(f"- {n}")
        return 2

    print("\n=== Placeholder scan ===")
    print("No '{{' / '}}' patterns remain in archive.")

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print(f"FAILED: {e}", file=sys.stderr)
        returncode = 1
        raise SystemExit(returncode)

